 const rein=player?'<path d="M163 124Q157 141 167 151Q180 161 196 160" stroke="#6f7d3a" stroke-width="2.2" fill="none" stroke-linecap="round"/><path d="M196 160q5-1 5-5q-4 0-3.4 3.4" stroke="#6f7d3a" stroke-width="1.8" fill="none" stroke-linecap="round"/><path d="M160 138q-5-1-6 3q4 1 6-3Z" fill="#8fb05a"/>':'';
