function sidebar(){$('#coins').textContent=state.coins;$('#wins').textContent=state.wins+' segrar';$('#teamName').textContent=state.name+' & '+state.frogName;$('#portrait').innerHTML=frog();$('#stats').innerHTML=stats().map((n,i)=>`<div class="stat"><span>${['Fart','Hopp','Uthållighet'][i]}</span><div class="bar"><i style="width:${n}%"></i></div><span>${n}</span></div>`).join('');$('#royalTrust').innerHTML=trustMeter()}
// Five menu groups; each group has small tabs inside it. The old tab names stay the same everywhere else.
const navGroups=[{id:'race',tabs:[['race','Lopp'],['cup','Mästerskap']]},{id:'team',tabs:[['care','Grodvän'],['frog','Utrustning'],['fairy','Älvan']]},{id:'adventure',tabs:[['adventure','Äventyr'],['astrid','Astrid'],['queen','Besöket',()=>typeof queenVisiting==='function'&&queenVisiting()],['castle','Slottet'],['forest','Hemliga skogen',()=>typeof unlocked!=='function'||unlocked('secretforest')]]},{id:'home',tabs:[['home','Gläntan'],['house','Svamphuset'],['fish','Fiska'],['fireflies','Eldflugor',()=>typeof unlocked!=='function'||unlocked('fireflies')],['memory','Memory',()=>typeof unlocked!=='function'||unlocked('memory')],['berries','Bärplockning',()=>typeof unlocked!=='function'||unlocked('berries')],['yard','Trädgården',()=>typeof unlocked!=='function'||unlocked('yard')]]},{id:'village',tabs:[['village','Älvbyn'],['shop','Butiken']]}];
const groupOf=t=>navGroups.find(g=>g.tabs.some(([k])=>k===t))||navGroups[0];const lastTabInGroup={};
function renderSubNav(){const box=$('#subNav');if(!box)return;const g=groupOf(tab);lastTabInGroup[g.id]=tab;const shown=g.tabs.filter(t=>!t[2]||t[2]()||t[0]===tab);if(shown.length<2){box.hidden=true;box.innerHTML='';return}box.hidden=false;box.innerHTML=shown.map(([k,n])=>`<button role="tab" data-subtab="${k}" aria-selected="${k===tab}">${n}</button>`).join('');{const sel=box.querySelector?.('[aria-selected="true"]');if(sel&&box.scrollWidth>box.clientWidth)box.scrollLeft=sel.offsetLeft-(box.clientWidth-sel.offsetWidth)/2}if(box.querySelectorAll)box.querySelectorAll('[data-subtab]').forEach(b=>b.onclick=()=>{if(running){toast('Avsluta loppet eller äventyret först – heja ditt team!');return}tab=b.dataset.subtab;render()})}
function goToGroup(id){const g=navGroups.find(g=>g.id===id)||navGroups[0];const last=g.tabs.find(t=>t[0]===lastTabInGroup[g.id]);tab=last&&(!last[2]||last[2]())?last[0]:g.tabs[0][0];render()}
const musicForTab={race:'meadow',frog:'meadow',fairy:'meadow',care:'glade',astrid:'castle',adventure:'adventure',cup:'castle',home:'glade',fish:'glade',house:'glade',shop:'village',queen:'castle',castle:'emerald',fireflies:'night',memory:'glade',berries:'glade',forest:'forest',yard:'glade',village:'village'};
function render(){document.body.classList.toggle('gardenView',['home','village'].includes(tab)&&state.hatched);setMusic(!state.hatched?'meadow':['home','fish'].includes(tab)&&state.garden?.night?'night':musicForTab[tab]||'meadow');if(!state.hatched){renderEgg();return}if(typeof ensureFrogs==='function')ensureFrogs();if(typeof checkUnlocks==='function')checkUnlocks();if(typeof applySeason==='function')applySeason();document.body.classList.remove('hatching');sidebar();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.group===groupOf(tab).id));renderSubNav();if(document.body.dataset)document.body.dataset.tab=tab;const activeNav=document.querySelector('nav button.active');if(activeNav?.scrollIntoView)activeNav.scrollIntoView({inline:'center',block:'nearest'});const c=$('#content');if(tab==='adventure'){renderAdventures();return}if(tab==='care'){renderCare();return}if(tab==='home'){renderHome();return}if(tab==='fish'&&typeof renderFishing==='function'){renderFishing();return}if(tab==='house'&&typeof renderHouse==='function'){renderHouse();return}if(tab==='shop'&&typeof renderShop==='function'){renderShop();return}if(tab==='queen'&&typeof renderQueen==='function'){renderQueen();return}if(tab==='castle'&&typeof renderCastle==='function'){renderCastle();return}if(tab==='fireflies'&&typeof renderFireflies==='function'){renderFireflies();return}if(tab==='memory'&&typeof renderMemory==='function'){renderMemory();return}if(tab==='berries'&&typeof renderBerries==='function'){renderBerries();return}if(tab==='forest'&&typeof renderForest==='function'){renderForest();return}if(tab==='yard'&&typeof renderYard==='function'){renderYard();return}if(tab==='village'){renderVillage();return}if(tab==='cup'){renderCup();return}if(tab==='astrid'){renderAstrid();return}if(tab==='race'){renderRaceTab(c)}else if(tab==='frog'){c.innerHTML=`<div class="sectionHead"><h2>${escapeText(genitive(state.frogName))} utrustningsbod</h2><span class="pill">Alla bonusar är aktiva</span></div><p class="statGuide"><strong>Fart</strong> gör det gröna hoppfältet bredare · <strong>Hopp</strong> ger längre skutt · <strong>Uthållighet</strong> gör att du tappar mindre fart vid en miss</p><div class="shop">${items.map(i=>`<article class="card"><div class="icon">${i.icon}</div><h3>${i.name}</h3><p>${i.desc}<br>+${i.bonus} ${['fart','hopp','uthållighet'][i.stat]}</p><button class="primary" data-buy="${i.id}" ${state.owned.includes(i.id)||state.coins<i.cost?'disabled':''}>${state.owned.includes(i.id)?'✓ Utrustad':'✦ '+i.cost+' · Köp'}</button></article>`).join('')}</div><div class="editor" style="margin-top:18px"><h3>En groda i din färg</h3><div class="options">${(typeof frogColorChoices==='function'?frogColorChoices():['#88ad55','#66aaa0','#c49b57','#9c8db5']).map(v=>`<button aria-label="Grodfärg ${v}" class="swatch ${state.frog===v?'chosen':''}" style="background:${v}" data-frog="${v}"></button>`).join('')}</div></div>${typeof wardrobeHTML==='function'?wardrobeHTML([['frogHat','Hatt'],['frogJewel','Smycke']],escapeText(genitive(state.frogName))+' garderob'):''}`;if(typeof wireWardrobe==='function')wireWardrobe(render);document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const i=items.find(i=>i.id===b.dataset.buy);if(!state.owned.includes(i.id)&&state.coins>=i.cost){state.coins-=i.cost;state.owned.push(i.id);save();render();toast(i.name+' är nu utrustade!')}});document.querySelectorAll('[data-frog]').forEach(b=>b.onclick=()=>{state.frog=b.dataset.frog;save();render()})}else{c.innerHTML=`<div class="sectionHead"><h2>Din älva, din stil</h2><span class="pill">Alla stilar är gratis</span></div><div class="editor"><div style="height:190px;text-align:center">${frog()}</div><label for="name">Älvans namn</label><input type="text" id="name" maxlength="18"><label>Frisyr</label><div class="options hairstyles">${[['short','Kort'],['long','Långt'],['curly','Lockigt'],['braid','Fläta'],['ponytail','Hästsvans'],['pigtails','Två tofsar'],['bun','Knut'],['twobraids','Två flätor'],['puffs','Afropuffar'],['bob','Rak page'],['wavy','Långt vågigt']].map(([v,n])=>`<button data-style="${v}" aria-pressed="${state.hairstyle===v}" class="${state.hairstyle===v?'chosen':''}">${n}</button>`).join('')}</div><label>Ögonform</label><div class="options hairstyles">${[['round','Runda'],['almond','Mandelformade'],['happy','Glatt slutna'],['wink','Blinkar'],['side','Tittar åt sidan'],['lashes','Långa fransar']].map(([v,n])=>`<button data-eyes="${v}" aria-pressed="${state.eyeShape===v}" class="${state.eyeShape===v?'chosen':''}">${n}</button>`).join('')}</div>${[['mouth','Muntyp',[['smile','Leende'],['big','Stort leende'],['straight','Liten rak mun'],['surprised','Förvånad'],['smirk','Busigt flin'],['tongue','Tungan ute'],['cat','Kattmun'],['gap','Tandglipa']]],['hairBand','Hårband och spännen',[['outfit','Som kläderna'],['none','Inget'],['#d9788a','Rosa'],['#79a7c0','Blått'],['#f1ce69','Gult'],['#8cc88a','Grönt'],['#fffaf0','Vitt']]],['headwear','Huvudbonad',[['none','Ingen'],...(state.cupWins>0?[['champion','Astrids mästarkrans']]:[]),...((state.headwearOwned||[]).includes('lucia')?[['lucia','Luciakrona']]:[]),['flowers','Blomsterkrans'],['crown','Krona'],['leaf','Lövhatt'],['mushroom','Svamphatt']]]].map(([key,label,choices])=>`<label>${label}</label><div class="options hairstyles">${choices.map(([v,n])=>`<button data-feature="${key}" data-choice="${v}" aria-pressed="${state[key]===v}" class="${state[key]===v?'chosen':''}">${n}</button>`).join('')}</div>`).join('')}<label>Älvans utseende</label><div class="options">${['Kvinnlig','Manlig'].map(v=>`<button data-gender="${v}" class="${state.gender===v?'chosen':''}">${v} älva</button>`).join('')}</div>${[['skin','Hudfärg',['#f7dfcc','#efc6a1','#d6a077','#b77b55','#89563d','#57382c']],['hair','Hårfärg',['#784c39','#e5c681','#333638','#ce795e','#211c1a','#4b3026','#a57449','#c79351','#ece1bd','#a5a29d','#e5e3de']],['outfit','Klädfärg',['#b68bc2','#79a7c0','#d99783','#789d61']],['eyeColor','Ögonfärg',['#6b4a2e','#8a6a2f','#4f7d4a','#4f7fb0','#7d8a8f','#7a5aa8']]].map(([key,label,colors])=>`<label>${label}</label><div class="options">${colors.map(v=>`<button aria-label="${label} ${v}" aria-pressed="${state[key]===v}" data-key="${key}" data-color="${v}" class="swatch ${state[key]===v?'chosen':''}" style="background:${v}"></button>`).join('')}</div>`).join('')}<p>✧ Din stil sparas automatiskt och följer med ut på banan.</p></div>${typeof wardrobeHTML==='function'?wardrobeHTML([['wings','Vingar'],['outfitStyle','Kläder'],['shoes','Skor'],['glasses','Glasögon'],['bag','Väska']],'Älvans garderob'):''}`;if(typeof wireWardrobe==='function')wireWardrobe(render);document.querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>{state.hairstyle=b.dataset.style;save();render()});document.querySelectorAll('[data-eyes]').forEach(b=>b.onclick=()=>{state.eyeShape=b.dataset.eyes;save();render()});document.querySelectorAll('[data-feature]').forEach(b=>b.onclick=()=>{state[b.dataset.feature]=b.dataset.choice;save();render()});$('#name').value=state.name;$('#name').oninput=e=>{state.name=e.target.value.trim()||'Dagg';save();sidebar()};document.querySelectorAll('[data-gender]').forEach(b=>b.onclick=()=>{state.gender=b.dataset.gender;save();render()});document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{state[b.dataset.key]=b.dataset.color;save();render()})}}
function mouthShape(){const mouths={smirk:'<path d="M150 93Q155 95.5 161.5 90.5" stroke="#8a4a40" stroke-width="1.2" fill="none" stroke-linecap="round"/>',tongue:'<path d="M149.5 91H161.5Q160.5 97.5 155.5 97.5Q150.5 97.5 149.5 91Z" fill="#653b35"/><ellipse cx="155.5" cy="97.4" rx="3" ry="2.5" fill="#e98b9a"/><path d="M155.5 95.6v2.6" stroke="#c96a79" stroke-width=".7"/>',cat:'<path d="M150.5 91.8Q153 94.8 155.5 91.8Q158 94.8 160.5 91.8" stroke="#8a4a40" stroke-width="1.15" fill="none" stroke-linecap="round"/>',gap:'<path d="M149.5 90.5H161.5Q160.5 97.5 155.5 97.5Q150.5 97.5 149.5 90.5Z" fill="#653b35"/><rect x="151.3" y="90.6" width="3.6" height="2.6" rx=".5" fill="#fff9ef"/><rect x="156.1" y="90.6" width="3.6" height="2.6" rx=".5" fill="#fff9ef"/>',smile:'<path d="M150 91Q155 97 161 91" fill="none" stroke="#8a4a40" stroke-width="1.15" stroke-linecap="round"/>',big:'<path d="M149 90H162Q160 101 155 99Q151 98 149 90Z" fill="#653b35"/><path d="M151 91H160L159 94H152Z" fill="#fff9ef"/>',straight:'<path d="M152 93H159" stroke="#8a4a40" stroke-width="1.2" stroke-linecap="round"/>',surprised:'<ellipse cx="155" cy="94" rx="3" ry="4" fill="#653b35"/>'};return '<g class="fairy-mouth">'+(mouths[state.mouth]||mouths.smile)+'</g>'}
