 const frame=y=>`<path d="M135.5 ${y}Q133 58 153 55.5Q173 58 170.5 ${y}Q168 ${y} 166.5 ${y-4}Q166 72 161 67Q157 63.5 153 63.5Q149 63.5 145 67Q140 72 139.5 ${y-4}Q138 ${y} 135.5 ${y}Z" fill="${c}"/>`;
