function patternShape(){if(state.pattern==='spots')return '<g fill="#263c43" opacity=".45"><circle cx="87" cy="175" r="5"/><circle cx="108" cy="163" r="5"/><circle cx="128" cy="174" r="5"/><circle cx="149" cy="159" r="4"/><circle cx="104" cy="190" r="4"/><circle cx="166" cy="171" r="4"/></g>';if(state.pattern==='patches')return '<g fill="#f5e7c2" opacity=".65"><path d="M73 174Q74 157 94 164T108 184Q93 199 80 184Z"/><path d="M120 163Q128 145 146 156T144 177Q125 182 120 163Z"/><path d="M153 180Q161 170 174 183T160 197Z"/></g>';return ''}
function eggArt(clicks=state.eggClicks){const n=Math.min(4,clicks);return `<svg viewBox="0 0 320 310" aria-hidden="true"><defs><radialGradient id="jelly"><stop stop-color="#f1fff7" stop-opacity=".25"/><stop offset=".75" stop-color="#c4e7d8" stop-opacity=".45"/><stop offset="1" stop-color="#f4fffa" stop-opacity=".9"/></radialGradient></defs><ellipse cx="160" cy="278" rx="112" ry="17" fill="#6d987c" opacity=".25"/><path d="M47 274Q140 227 275 268Q190 305 47 274L140 271Z" fill="#8aab72"/><ellipse cx="160" cy="156" rx="105" ry="114" fill="url(#jelly)" stroke="#f7fff9" stroke-width="3"/><ellipse cx="162" cy="166" rx="46" ry="52" fill="#364a40"/><ellipse cx="150" cy="149" rx="28" ry="32" fill="#526359"/><path d="M86 132Q89 87 121 75" stroke="white" stroke-width="10" opacity=".65" stroke-linecap="round" fill="none"/><circle cx="234" cy="194" r="9" fill="white" opacity=".4"/><g stroke="#efffe9" stroke-width="3" fill="none" stroke-linejoin="round">${n>0?'<path d="M162 112L150 139 168 151 157 175"/>':''}${n>1?'<path d="M157 175L181 185 167 219"/>':''}${n>2?'<path d="M168 151L192 140 205 157M150 139L127 151 116 143"/>':''}${n>3?'<path d="M157 175L134 188 124 211M181 185L204 199"/>':''}</g><g fill="#fff9cb"><path d="M258 68l3 9 9 3-9 3-3 9-3-9-9-3 9-3Z"/><circle cx="59" cy="205" r="3"/></g></svg>`}
function renderEgg(){document.body.classList.add('hatching');if($('#subNav'))$('#subNav').hidden=true;$('#coins').textContent=state.coins;$('#content').innerHTML=`<section class="eggScreen"><div class="eyebrow">DITT ÄVENTYR BÖRJAR HÄR</div><h2>Vem gömmer sig i ägget?</h2><p>Ett litet grodägg i en magisk gelébubbla.<br>Klicka fem gånger och möt din nya vän.</p><button class="eggButton" aria-label="Klicka på det mystiska ägget">${eggArt()}</button><div class="eggProgress" aria-label="${state.eggClicks} av 5 klick">${[0,1,2,3,4].map(i=>`<span class="${i<state.eggClicks?'filled':''}"></span>`).join('')}</div><p role="status">${['Ett försiktigt klick kan väcka någon där inne…','Det rör sig i ägget!','En liten spricka… fortsätt!','Snart får du träffa din groda!','Bara ett klick till!'][state.eggClicks]||''}</p></section>`;$('.eggButton').onclick=()=>{state.eggClicks=Math.min(5,state.eggClicks+1);if(state.eggClicks===5){const pick=a=>a[Math.floor(Math.random()*a.length)];state.frog=pick(['#88ad55','#66aaa0','#c49b57','#9c8db5','#cc8d9c','#82b8cf']);state.pattern=pick(['plain','spots','patches']);state.baseStats=[0,1,2].map(()=>35+Math.floor(Math.random()*26));state.hatched=true;save();showHatched()}else{save();renderEgg()}}}
function showHatched(){$('#content').innerHTML=`<section class="eggScreen reveal"><div class="eyebrow">VÄLKOMMEN TILL VÄRLDEN</div><h2>Du fick ${escapeText(state.frogName)}!</h2><div class="newFrog">${frog()}</div><p>${{plain:'En enfärgad',spots:'En prickig',patches:'En fläckig'}[state.pattern]} liten groda, redo för äventyr.</p><div class="hatchStats">${state.baseStats.map((v,i)=>`<div><strong>${v}</strong><span>${['Fart','Hopp','Uthållighet'][i]}</span></div>`).join('')}</div><p>Det här är din grodas grundegenskaper.<br>Utrustning gör den ännu bättre!</p><button class="primary" id="meetFairy">Välj din älvas frisyr →</button></section>`;$('#meetFairy').onclick=()=>{tab='fairy';render()}}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{if(running){toast('Avsluta loppet eller äventyret först – heja ditt team!');return}goToGroup(b.dataset.group)});$('#customize').onclick=()=>{if(running)return;tab='fairy';render()};render();
function musicButton(){const b=$('#musicToggle');if(!b)return;const on=state.music!==false;b.classList.toggle('off',!on);b.setAttribute('aria-expanded',!!$('#musicMenu')&&!$('#musicMenu').hidden);b.setAttribute('aria-label',on?'Välj musik':'Musik av, välj musik')}
// The 🎵 button opens a small menu: off, follow the place, or one chosen song.
function musicMenuHTML(){const on=state.music!==false,pick=on?state.musicChoice||'auto':'off';const opt=(v,label)=>`<button type="button" role="menuitemradio" aria-checked="${pick===v}" data-music="${v}">${label}</button>`;return `<div class="musicMenuHead">Välj musik</div>${opt('off','Av')}${opt('auto','Följer platsen')}<div class="musicMenuList">${Object.keys(musicThemes).map(k=>opt(k,'♪ '+(musicNames[k]||k))).join('')}</div>`}
function toggleMusicMenu(show){let m=$('#musicMenu');if(!m&&document.body.appendChild){m=document.createElement('div');m.id='musicMenu';m.className='musicMenu';m.setAttribute('role','menu');m.hidden=true;document.body.appendChild(m)}if(!m)return;show=show??m.hidden;m.hidden=!show;if(show){m.innerHTML=musicMenuHTML();const r=$('#musicToggle').getBoundingClientRect();m.style.top=(r.bottom+scrollY+8)+'px';m.style.right=Math.max(12,innerWidth-r.right)+'px';m.querySelectorAll('[data-music]').forEach(b=>b.onclick=()=>{const v=b.dataset.music;if(v==='off'){setMusicEnabled(false)}else setMusicChoice(v==='auto'?null:v);toggleMusicMenu(false)})}musicButton()}
if($('#musicToggle')){$('#musicToggle').onclick=e=>{e.stopPropagation?.();toggleMusicMenu()};musicButton();if(document.addEventListener)document.addEventListener('click',e=>{const m=$('#musicMenu');if(m&&!m.hidden&&!m.contains(e.target))toggleMusicMenu(false)})}
// Offline play and "add to home screen".
if(typeof navigator!=='undefined'&&'serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('sw.js').catch(()=>{});
let installPrompt=null;
function installHint(){const box=$('#installHint');if(!box)return;const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone;const ios=/iphone|ipad|ipod/i.test(navigator.userAgent);const small=matchMedia('(max-width: 700px)').matches;if(standalone||state.installDismissed||!state.hatched||!small||!(installPrompt||ios)){box.hidden=true;return}box.hidden=false;box.innerHTML=`<span>🐸 Lägg spelet på hemskärmen – då funkar det även utan internet.${installPrompt?'':' Tryck på <b>Dela</b> och sedan <b>Lägg till på hemskärmen</b>.'}</span>${installPrompt?'<button class="primary" id="installNow">Lägg till</button>':''}<button class="installClose" id="installClose" aria-label="Stäng">✕</button>`;if($('#installNow'))$('#installNow').onclick=async()=>{installPrompt.prompt();await installPrompt.userChoice.catch(()=>{});installPrompt=null;installHint()};$('#installClose').onclick=()=>{state.installDismissed=true;save();installHint()}}
addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;installHint()});
installHint();
function soundButton(){const b=$('#soundToggle');if(!b)return;const on=state.sound!==false;b.textContent=on?'🔊':'🔈';b.setAttribute('aria-pressed',on);b.setAttribute('aria-label',on?'Ljud på':'Ljud av')}if($('#soundToggle')){$('#soundToggle').onclick=()=>{state.sound=state.sound===false;save();soundButton();sfx('land')};soundButton()}

// Invite a friend: the phone's own share sheet, or copy the link.
async function inviteFriend(){const say=t=>typeof enLang==='function'&&enLang()&&typeof tr==='function'?tr(t):t;const url=location.origin+location.pathname;try{if(navigator.share){await navigator.share({title:'The Big Frog Race',text:say('Följ med till Älvskogen och tävla med din egen groda!'),url});return}await navigator.clipboard.writeText(url);toast('Länken är kopierad – skicka den till en kompis!')}catch(e){if(e?.name!=='AbortError')toast('Länken till spelet: '+url)}}
if($('#invite'))$('#invite').onclick=inviteFriend;
